-- 0009: 상황(데일리/출근/데이트) 점수를 -3~+3로 다시 매김 (사용자 요청, 2026-10-02)
-- 기존 값은 0008 시드의 규칙 생성값(데일리 전부 3, 출근/데이트 1 또는 3, 마이너스 없음).
-- 되돌리려면 0008_catalog_seed.sql 의 situation 줄을 다시 실행.
-- 코드에서는 lib/catalog-recommendation.ts 의 situation 가중치를 6 -> 18 로 올려 함께 사용.
update public.catalog_tags t set score = s.new_score from (select t2.id, case t2.value when 'daily' then case when p.name ~ '이브닝|파티' then -2 when p.formality = 'formal' then 0 when p.name ~ '티셔츠' then 3 when p.name ~ '슬랙스|테일러드|펌프스|힐' then 1 when p.formality = 'smart' then 2 else 3 end when 'work' then case when p.name ~ '이브닝|파티|슬리퍼|하우스|코르셋|스위트하트|마이크로|오프숄더|홀터|원숄더|캉캉|조거|트랙|스웨트|러닝|하이킹|레인|윈터' then -3 when p.name ~ '후드티|맨투맨|카고|바시티|컴뱃|샌들|플리스|야상|유틸리티|워크웨어|초어|패딩|나시|민소매|탱크|미니 스커트|버블|벨트백|백팩|메신저|클로그|하프집업|비치|바스켓|스트로|파카|아노락|나일론|스니커즈' then -2 when p.name ~ '티셔츠' then 1 when p.name ~ '데님' then 0 when p.name ~ '슬랙스|테일러드|로퍼|블라우스|셔츠|토트|트렌치|펜슬|트위드|구조적|스트레이트 슬림|치노|니트 베스트' then 3 when p.formality = 'smart' or p.name ~ '가디건|플랫|메리제인|발레리나|미디 스커트|코트|숄더백|와이드 팬츠|스트레이트|스커트|니트|펌프스|힐|슬링백' then 2 when p.name ~ '크롭' then 0 else 1 end when 'date' then case when p.name ~ '후드티|맨투맨|조거|트랙|스웨트|러닝|하이킹|트레이닝|슬리퍼|하우스|플리스|하프집업|레인|윈터|아노락|파카' then -3 when p.name ~ '카고|백팩|벨트백|메신저|컴뱃|야상|워크웨어|초어|유틸리티|패딩|바시티|나일론|캔버스|스니커즈|클로그|비치|쇼퍼' then -2 when p.name ~ '블라우스|새틴|레이스|리본|프릴|러플|셔링|드레이프|원숄더|오프숄더|홀터|플리츠|메리제인|발레리나|슬링백|펌프스|힐|클러치|미니백|호보|새들|하프문|바게트|볼레로|케이프|캉캉|쉬폰|퍼프|진주|코르셋|스위트하트|골드버튼|트위드|벨티드|페플럼|라피아|체인' then 3 when p.name ~ '티셔츠' then 1 when p.formality = 'formal' or p.name ~ '스커트|가디건|플랫|숄더백|토트|로퍼|트렌치|골지|니트|셔츠|코트' then 2 else 0 end end as new_score from public.catalog_tags t2 join public.catalog_products p on p.id = t2.product_id where t2.dimension = 'situation') s where t.id = s.id and t.score is distinct from s.new_score;
